CREATE VIEW "TEST_AP"."B1_BPTransactionsView" ( "CardCode", "DocDate" ) AS (((((SELECT DISTINCT T0."CardCode", T0."DocDate" FROM  "TEST_AP"."B1_GDPDocsView" T0) UNION (SELECT DISTINCT T0."CardCode", T0."DocDate" FROM  "TEST_AP"."OVPM" T0)) UNION (SELECT DISTINCT T0."CardCode", T0."DocDate" FROM  "TEST_AP"."ORCT" T0)) UNION (SELECT DISTINCT T0."VendorCode", T0."PmntDate" FROM  "TEST_AP"."OCHO" T0)) UNION (SELECT DISTINCT T0."ShortName", T0."RefDate" FROM  "TEST_AP"."JDT1" T0)) WITH READ ONLY